------------------------------------------------------------
----- ROOT ID FUNCTION FOR: [Comment].[parentCommentID]
------------------------------------------------------------
IF OBJECT_ID('[higherlogic_vanilla].[fnCommentparentCommentID_GetRootID]', 'IF') IS NOT NULL
    DROP FUNCTION [higherlogic_vanilla].[fnCommentparentCommentID_GetRootID];
GO

CREATE FUNCTION [higherlogic_vanilla].[fnCommentparentCommentID_GetRootID]
(
    @RecordID int,
    @ParentID int
)
RETURNS TABLE
AS
RETURN
(
    WITH CTE_RootParent AS (
        SELECT
            [commentID],
            [parentCommentID],
            [commentID] AS [RootParentID],
            0 AS [Depth]
        FROM
            [higherlogic_vanilla].[Comment]
        WHERE
            [commentID] = COALESCE(@ParentID, @RecordID)

        UNION ALL

        SELECT
            c.[commentID],
            c.[parentCommentID],
            c.[commentID] AS [RootParentID],
            p.[Depth] + 1 AS [Depth]
        FROM
            [higherlogic_vanilla].[Comment] c
        INNER JOIN
            CTE_RootParent p ON c.[commentID] = p.[parentCommentID]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [parentCommentID] IS NULL
    ORDER BY
        [RootParentID]
);
GO

